set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
import ast,hashlib,json,shutil
from pathlib import Path
stage=Path('/tmp/travel-mixed-stage-20261012/service')
old=Path('rag/service/ticket_service.py');new=stage/'ticket_service.py'
def fn(path,name):
    return ast.dump(next(n for n in ast.parse(path.read_text()).body if isinstance(n,ast.FunctionDef) and n.name==name))
assert fn(old,'is_ticket_question')==fn(new,'is_ticket_question')
for filename in ('intent_classifier.py','store_contract.py','semantic_router.py','routing_prototypes.json'):
    assert (Path('rag/service')/filename).read_bytes()==(stage/filename).read_bytes(),filename
backup=Path('deploy/backups/mixed-2026-10-12');backup.mkdir(parents=True,exist_ok=False)
for filename in ('ticket_service.py','retrieval_server.py'):
    shutil.copyfile(Path('rag/service')/filename,backup/filename)
(backup/'manifest.json').write_text(json.dumps({'old_mixed_flag':'0','no_secrets_archived':True,'rule_unchanged':True,'source_sha256':{f:hashlib.sha256((backup/f).read_bytes()).hexdigest() for f in ('ticket_service.py','retrieval_server.py')}}))
for filename in ('mixed_service.py','ticket_service.py','retrieval_server.py'):
    shutil.copyfile(stage/filename,Path('rag/service')/filename)
shutil.copyfile('/tmp/travel-mixed-stage-20261012/eval/test_mixed_service.py','rag/eval/test_mixed_service.py')
p=Path('.env');lines=p.read_text().splitlines()
lines=[line for line in lines if not line.startswith('RAG_MIXED_ENABLED=')]
lines.append('RAG_MIXED_ENABLED=1');p.write_text('\n'.join(lines)+'\n')
print('Mixed enabled; existing classifier, thresholds and search source untouched')
PY
echo  | base64 -d > rag/eval/verify_mixed_live.py
bash rag/service/stop_retrieval_server.sh
bash rag/service/start_retrieval_server.sh
PYTHONPATH=rag .venv/bin/python rag/eval/verify_mixed_live.py --output rag/eval/reports/mixed_v1_live_run1.json
